page='''<!doctype html><html lang="hu"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Mozdulj! v0.11 – Korrektúra és frissítés</title>
<style>
:root{--p:#6c4ca9;--pl:#f2ebfa;--te:#287b79;--ink:#28243c;--mut:#776f87;--b:#e6dfed;--bg:#f7f4fa}*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink)}button,input,textarea,select{font:inherit}button{border:0;border-radius:14px;padding:11px 14px;background:var(--p);color:white;cursor:pointer;font-weight:700}button.light{background:#eee8f9;color:var(--p)}button.danger{color:#913d62;background:#f9e8ed}button:disabled{opacity:.5}input,textarea,select{width:100%;padding:11px;border:1px solid #d9d2e4;border-radius:10px;background:white;color:var(--ink)}textarea{min-height:87px}h1{margin:0;font-size:24px}h2{font-size:19px;margin:0 0 12px}p{margin:5px 0 12px}.muted{color:var(--mut);font-size:13px}.shell{max-width:1040px;margin:22px auto;background:white;min-height:88vh;border:1px solid var(--b);border-radius:27px;box-shadow:0 18px 55px #55497915;display:grid;grid-template-columns:228px 1fr;overflow:hidden}.side{background:#faf8fe;padding:24px 15px;border-right:1px solid var(--b)}.brand{font-size:26px;font-weight:850;color:var(--p);margin-bottom:27px}.nav{background:transparent;color:var(--ink);text-align:left;width:100%;margin-bottom:7px}.nav.active{background:#ede5fa;color:var(--p)}main{min-width:0;padding:26px}section{display:none}section.active{display:block}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:16px}.tile{border:1px solid var(--b);padding:14px;border-radius:15px;margin-bottom:10px;display:flex;gap:13px;align-items:center}.thumb{width:66px;height:60px;background:linear-gradient(130deg,#f5eafb,#def2ef);border-radius:12px;display:grid;place-items:center;font-size:26px;flex:none}.grow{flex:1;min-width:0}.grow strong{display:block}.actions{display:flex;gap:5px;flex-wrap:wrap}.tiny{font-size:12px;padding:8px}.tag{background:#f0eafa;border-radius:20px;font-size:11px;font-weight:700;color:#664c9f;padding:5px 8px}.chip{background:#e2f5ef;color:var(--te)}.filters{display:grid;grid-template-columns:1fr auto;gap:10px;margin:13px 0}.card{background:#fcfafe;border:1px solid var(--b);border-radius:18px;padding:17px;margin-bottom:17px}.field{margin-bottom:12px}.field label{font-weight:700;font-size:12px;display:block;margin-bottom:4px;color:var(--mut)}.fixed{position:sticky;bottom:-26px;background:#fffefa;border-top:1px solid var(--b);padding:13px 0;display:flex;justify-content:flex-end;gap:9px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.progress{height:9px;background:#eee9f5;border-radius:50px;overflow:hidden}.progress>div{height:100%;background:var(--p);width:65%}.row{display:flex;align-items:center;justify-content:space-between;gap:10px}.error{background:#fff0f0;color:#a04158;padding:11px;border-radius:11px}.notice{background:#edf9f6;color:#1d716e;padding:12px;border-radius:12px}.board{background:#f6effb;border:1px solid var(--b);border-radius:15px;padding:9px}#poseSvg{width:100%;max-height:440px;touch-action:none;user-select:none;display:block}.joint{fill:#3aafaa;stroke:white;stroke-width:1.3;cursor:grab}.bone{stroke:#7f5ca9;stroke-width:2.4;stroke-linecap:round}.arrow{stroke:#c87066;stroke-width:1.7;fill:none}.hidden{display:none!important}#notice{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:5;background:#2d2752;color:white;padding:12px 16px;border-radius:12px;display:none} @media(max-width:750px){.shell{display:block;margin:0;border-radius:0;border:0}.side{display:flex;gap:4px;padding:8px;position:sticky;top:0;z-index:3;overflow:auto;border-bottom:1px solid var(--b)}.brand{font-size:18px;margin:8px 4px 0}.nav{width:auto;min-width:max-content;font-size:12px;padding:9px;margin:0}main{padding:18px 14px 55px}.two{grid-template-columns:1fr}.tile{flex-wrap:wrap}.actions{width:100%}.fixed{bottom:-55px}}
</style></head><body>
<div class="shell"><aside class="side"><div class="brand">✿ Mozdulj!</div><button class="nav active" data-screen="catalog">▦ Gyakorlattár</button><button class="nav" data-screen="editor">✎ Korrektúra</button><button class="nav" data-screen="pose">♧ Testpontok</button><button class="nav" data-screen="storage">↕ Adatmentés</button></aside>
<main><section class="active" id="catalog"><div class="head"><div><p class="muted">V0.11 · MŰKÖDŐ UI-ELŐNÉZET</p><h1>Gyakorlattár</h1><p class="muted">Az alapgyakorlat leírása és ábrája javítható. A cél, testtáj és típus védett.</p></div><span class="tag">132 alapgyakorlat</span></div><div class="filters"><input id="search" placeholder="Keresés név vagy testtáj szerint"/><select id="filter"><option value="all">Összes</option><option value="patched">Módosított</option><option value="unmodified">Eredeti</option></select></div><p class="muted" id="counter"></p><div id="results"></div><button id="more" class="light" style="width:100%">További gyakorlatok betöltése</button></section>
<section id="editor"><div class="head"><div><p class="muted">ALAPGYAKORLAT · CSAK TARTALOM</p><h1 id="editingName">Gyakorlat</h1></div><span class="tag">Védett metaadat</span></div><div class="card" id="locked"></div><div class="card"><h2>Leírás javítása</h2><div class="field"><label>Rövid leírás *</label><textarea id="summary"></textarea></div><div class="field"><label>Kiinduló helyzet *</label><textarea id="starting"></textarea></div><div class="field"><label>Végrehajtási lépések (soronként) *</label><textarea id="steps" rows="5"></textarea></div><div class="field"><label>Gyakori hibák (soronként)</label><textarea id="mistakes"></textarea></div><div class="field"><label>Biztonsági megjegyzés *</label><textarea id="safety"></textarea></div></div><div class="card"><h2>Ábra</h2><p id="poseStatus" class="muted"></p><button id="editPose" class="light">Testpontok és mozgásnyilak módosítása</button></div><p id="editorError" class="error hidden"></p><div class="fixed"><button id="cancel" class="light">Mégse</button><button id="reset" class="danger">Eredeti visszaállítása</button><button id="save">Korrektúra mentése</button></div></section>
<section id="pose"><div class="head"><div><p class="muted">INTERAKTÍV SZEMLÉLTETŐ PÓZ</p><h1>Testpontszerkesztő</h1></div><span class="tag">16 ízületi pont</span></div><div class="two"><div class="board"><svg id="poseSvg" viewBox="0 0 100 110" aria-label="Áthelyezhető testpontok és nyilak"></svg></div><div class="card"><div class="field"><label>Mozgásfázis</label><select id="frame"></select></div><div class="field"><label>Nézőpont</label><select id="view"><option value="front">Elölnézet</option><option value="side">Oldalnézet</option><option value="three-quarter">Háromnegyedes</option></select></div><label><input type="checkbox" id="limb" style="width:auto" checked/> Végtag együtt mozgatása</label><p class="muted">Húzd a türkiz ízületi pontokat. Az ábra szemléltető, nem orvosi pontosságú.</p><button class="light" id="arrow">＋ Nyíl hozzáadása (két kattintás)</button><button class="light" id="removeArrow">Utolsó nyíl törlése</button><p id="poseMessage" class="muted"></p><div class="fixed"><button id="poseBack" class="light">Mégse</button><button id="poseSave">Ábra elfogadása</button></div></div></div></section>
<section id="storage"><p class="muted">APK-FRISSÍTÉS · ADATMEGŐRZÉS</p><h1>Adatok biztonsága</h1><div class="card"><h2>A gyakorlatok külön JSON-ban élnek</h2><p>A beépített adatok nem íródnak át. A saját szöveg- és ábrakorrektúráid külön felülírásokként tárolódnak.</p><button id="exportLibrary">Könyvtárexport – v2 JSON</button></div><div class="card"><h2>Teljes adatmentés</h2><p>Az alkalmazásban a profil, kedvencek, XP, streak, badge-ek, napi tervek és saját gyakorlatok is egyben exportálhatók. A böngészős előnézet csak a korrektúrákat demonstrálja, nem az Androidon mentett haladást.</p><div class="notice">A normál APK-frissítés megtartja az AppDataDirectory fájljait, ha az alkalmazásazonosító és az aláírás megegyezik. A törlés nem frissítés!</div></div></section></main></div><div id="notice"></div>
<script type="application/json" id="seed">__EXERCISES__</script><script>
(()=>{const base=JSON.parse(document.getElementById('seed').textContent),byId=Object.fromEntries(base.map(e=>[e.id,e]));let patches={};try{patches=JSON.parse(localStorage.getItem('mozdulj-v11-preview-overrides')||'{}')}catch{}const $=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));let activeId=null,draft=null,pose=null,frameIdx=0,drag=null,arrowStart=null,count=12,matches=base;const bones=[['head','neck'],['neck','leftShoulder'],['neck','rightShoulder'],['leftShoulder','leftElbow'],['rightShoulder','rightElbow'],['leftElbow','leftWrist'],['rightElbow','rightWrist'],['leftShoulder','leftHip'],['rightShoulder','rightHip'],['leftHip','rightHip'],['leftHip','leftKnee'],['rightHip','rightKnee'],['leftKnee','leftAnkle'],['rightKnee','rightAnkle'],['leftAnkle','leftToe'],['rightAnkle','rightToe']];const children={leftShoulder:['leftElbow','leftWrist'],rightShoulder:['rightElbow','rightWrist'],leftElbow:['leftWrist'],rightElbow:['rightWrist'],leftHip:['leftKnee','leftAnkle','leftToe'],rightHip:['rightKnee','rightAnkle','rightToe'],leftKnee:['leftAnkle','leftToe'],rightKnee:['rightAnkle','rightToe'],leftAnkle:['leftToe'],rightAnkle:['rightToe'],neck:['head']};function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function notice(x){$('notice').textContent=x;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',2300)}function tab(t){document.querySelectorAll('section').forEach(s=>s.classList.toggle('active',s.id===t));document.querySelectorAll('[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===t));window.scrollTo(0,0)}document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>tab(b.dataset.screen));function draw(){let q=$('search').value.toLocaleLowerCase('hu'),mode=$('filter').value;matches=base.filter(e=>(!q||[e.name,...e.regions].join(' ').toLocaleLowerCase('hu').includes(q))&&(mode==='all'||(mode==='patched'&&patches[e.id])||(mode==='unmodified'&&!patches[e.id])));count=Math.min(count,matches.length);$('results').innerHTML=matches.slice(0,count).map(e=>`<div class="tile"><div class="thumb">♧</div><div class="grow"><strong>${esc(e.name)}</strong><span class="muted">${esc(e.category)} · ${esc(e.regions.join(', '))}</span><br><span class="tag ${patches[e.id]?'chip':''}">${patches[e.id]?'Helyileg javított':'Eredeti'}</span></div><div class="actions"><button class="tiny light" data-edit="${esc(e.id)}">Leírás / ábra javítása</button></div></div>`).join('');$('counter').textContent=`${Math.min(count,matches.length)} / ${matches.length} gyakorlat`;$('more').classList.toggle('hidden',count>=matches.length);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));}function filter(){count=12;draw()}$('search').oninput=filter;$('filter').onchange=filter;$('more').onclick=()=>{count+=12;draw()};window.addEventListener('scroll',()=>{if($('catalog').classList.contains('active')&&window.innerHeight+window.scrollY>document.body.scrollHeight-180&&count<matches.length){count+=12;draw()}});
function persist(){try{localStorage.setItem('mozdulj-v11-preview-overrides',JSON.stringify(patches))}catch{}}function editorRead(){draft.summary=$('summary').value.trim();draft.startingPosition=$('starting').value.trim();draft.steps=$('steps').value.split('\n').map(x=>x.trim()).filter(Boolean);draft.commonMistakes=$('mistakes').value.split('\n').map(x=>x.trim()).filter(Boolean);draft.safetyNote=$('safety').value.trim()}function edit(id){activeId=id;const e=byId[id];draft=copy(patches[id]||{exerciseId:id,baseRevision:e.revision,summary:e.summary,startingPosition:e.startingPosition,steps:e.steps,commonMistakes:e.commonMistakes,safetyNote:e.safetyNote,pose:e.pose});$('editingName').textContent=e.name;$('locked').innerHTML=`<strong>Védett adatok – nem módosíthatók</strong><p class="muted">${esc(e.category)} · ${esc(e.regions.join(', '))} · ${esc(e.phase)} · ${e.difficulty}/3 nehézség · ${esc(e.measure==='time'?(e.targetSeconds+' mp'):'ismétlés')} · ${esc(e.equipment.join(', ')||'eszköz nélkül')}</p>`;for(const [id,key] of [['summary','summary'],['starting','startingPosition'],['safety','safetyNote']])$(id).value=draft[key]||'';$('steps').value=(draft.steps||[]).join('\n');$('mistakes').value=(draft.commonMistakes||[]).join('\n');$('editorError').classList.add('hidden');$('reset').disabled=!patches[id];status();tab('editor')}function status(){$('poseStatus').textContent=draft.pose?.frames?.length?`${draft.pose.frames.length} fázis · ${draft.pose.arrows?.length||0} mozgásnyíl`:'Ábra nélkül is elmenthető.'}$('cancel').onclick=()=>tab('catalog');$('save').onclick=()=>{editorRead();if(!draft.summary||!draft.startingPosition||!draft.steps.length||!draft.safetyNote){$('editorError').textContent='Rövid leírás, kiinduló helyzet, legalább egy lépés és biztonsági megjegyzés szükséges.';$('editorError').classList.remove('hidden');return;}patches[activeId]=copy(draft);persist();notice('Korrektúra mentve (böngészős előnézet).');draw();tab('catalog')};$('reset').onclick=()=>{if(!confirm('Visszaállítod az eredeti szöveget és ábrát?'))return;delete patches[activeId];persist();draw();tab('catalog');notice('Eredeti tartalom visszaállítva.')};
$('editPose').onclick=()=>{editorRead();pose=copy(draft.pose||{frames:[],arrows:[],view:'front'});if(!pose.frames?.length){notice('Az eredeti ábra ennél a feladatnál üres.');return;}frameIdx=0;arrowStart=null;frames();tab('pose')};function frames(){$('frame').innerHTML=pose.frames.map((x,i)=>`<option value="${i}">${esc(x.label||'Fázis '+(i+1))}</option>`).join('');$('frame').value=String(frameIdx);$('view').value=pose.view||'front';paint()}$('frame').onchange=()=>{frameIdx=Number($('frame').value);paint()};$('view').onchange=()=>pose.view=$('view').value;function paint(){let j=pose.frames[frameIdx].joints,arrows=(pose.arrows||[]).filter(a=>a.frameIndex===frameIdx);let svg='<defs><marker id="arrowtip" markerWidth="4" markerHeight="4" refX="3" refY="2" orient="auto"><path d="M0 0 L4 2 L0 4" stroke="#c87066" fill="none"/></marker></defs>';for(let z=10;z<=100;z+=10)svg+=`<path d="M${z} 0V110 M0 ${z}H100" stroke="#ded5ea" stroke-width=".25"/>`;for(const [a,b]of bones)if(j[a]&&j[b])svg+=`<line class="bone" x1="${j[a].x}" y1="${j[a].y}" x2="${j[b].x}" y2="${j[b].y}"/>`;for(const a of arrows)svg+=`<path class="arrow" marker-end="url(#arrowtip)" d="M${a.startX} ${a.startY} ${a.type==='line'?'L':'Q'}${a.type==='line'?'':`${(a.startX+a.endX)/2} ${Math.max(0,(a.startY+a.endY)/2-9)} `}${a.endX} ${a.endY}"/>`;for(const [name,v]of Object.entries(j))svg+=`<circle class="joint" data-joint="${esc(name)}" cx="${v.x}" cy="${v.y}" r="2.4"/>`;$('poseSvg').innerHTML=svg;}function loc(evt){let s=$('poseSvg'),p=s.createSVGPoint();p.x=evt.clientX;p.y=evt.clientY;let m=s.getScreenCTM();if(!m)return null;let q=p.matrixTransform(m.inverse());return{x:Math.max(0,Math.min(100,q.x)),y:Math.max(0,Math.min(100,q.y))}}let arrowMode=false;$('arrow').onclick=()=>{arrowMode=!arrowMode;arrowStart=null;$('poseMessage').textContent=arrowMode?'Kattints a nyíl kezdő- és végpontjára.':'Nyílmód kikapcsolva.'};$('poseSvg').addEventListener('pointerdown',e=>{let p=loc(e);if(!p)return;if(arrowMode){if(arrowStart){pose.arrows.push({frameIndex:frameIdx,type:'curve',startX:arrowStart.x,startY:arrowStart.y,endX:p.x,endY:p.y});arrowStart=null;arrowMode=false;paint();}else arrowStart=p;return;}let key=e.target.dataset.joint;if(!key)return;drag=key;$('poseSvg').setPointerCapture(e.pointerId)});$('poseSvg').addEventListener('pointermove',e=>{if(!drag)return;let p=loc(e);if(!p)return;let j=pose.frames[frameIdx].joints,old=j[drag],dx=p.x-old.x,dy=p.y-old.y,names=[drag,...($('limb').checked?(children[drag]||[]):[])];let points=names.filter(k=>j[k]).map(k=>j[k]);let minX=Math.min(...points.map(k=>k.x)),maxX=Math.max(...points.map(k=>k.x)),minY=Math.min(...points.map(k=>k.y)),maxY=Math.max(...points.map(k=>k.y));dx=Math.max(-minX,Math.min(100-maxX,dx));dy=Math.max(-minY,Math.min(100-maxY,dy));for(let key of names){if(j[key]){j[key].x+=dx;j[key].y+=dy}}paint()});for(const e of ['pointerup','pointercancel'])$('poseSvg').addEventListener(e,()=>drag=null);$('removeArrow').onclick=()=>{pose.arrows.pop();paint()};$('poseSave').onclick=()=>{draft.pose=copy(pose);status();tab('editor')};$('poseBack').onclick=()=>tab('editor');
function download(name,data){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}$('exportLibrary').onclick=()=>{download('mozdulj-konyvtar-v11.json',{format:'mozdulj.library.v2',schemaVersion:2,builtInCatalogVersion:5,builtInSnapshot:base,disabledBuiltInIds:[],builtInContentOverrides:Object.values(patches),userExercises:[]});notice('Könyvtár-korrektúrák exportálva.')};draw()})();
</script></body></html>'''
(root/'docs/UI_v11_interaktiv.html').write_text(page.replace('__EXERCISES__',ex_json).replace("split('\n')", "split('\\n')").replace("join('\n')", "join('\\n')"))
